#pragma once

// Runtime check that the game's live Scrooby loader can read a .p3d generated by
// our P3DWriter, WITHOUT replacing any shipping .p3d on disk. Called once at
// gameplay startup; prints a pass/fail line to the console. Safe to call even if
// Scrooby is not yet fully initialized (it then reports "not available").
namespace LobbyRuntimeTest
{
    // Generates a small Scrooby project to a temp .p3d file, loads it through
    // Scrooby::App->LoadProject, and reports whether the loader accepted it.
    // Returns 0 if the test ran, -1 if Scrooby is unavailable/not ready.
    int Run();
}